@page "/settings"
@inject Services.ThemeState ThemeState
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="settings-panel">
    <div class="setting-group">
        <label>Theme Mode</label>
        <select @bind="selectedMode" @bind:after="ApplyTheme">
            <option value="@Services.ThemeMode.Light">Light</option>
            <option value="@Services.ThemeMode.Dark">Dark</option>
            <option value="@Services.ThemeMode.System">System</option>
        </select>
    </div>

    <div class="setting-group">
        <label>Accent Color</label>
        <input type="color" @bind="selectedColor" @bind:after="ApplyTheme" />
        <span class="color-label">@selectedColor</span>
    </div>
</div>

<p class="status-message">
    Current: <strong>@ThemeState.Mode</strong> mode with accent
    <span style="color: @ThemeState.AccentColor; font-weight: bold;">@ThemeState.AccentColor</span>
</p>

@code {
    private Services.ThemeMode selectedMode;
    private string selectedColor = "#0078d4";

    protected override void OnInitialized()
    {
        selectedMode = ThemeState.Mode;
        selectedColor = ThemeState.AccentColor;
        ThemeState.OnChange += HandleThemeChanged;
    }

    private void ApplyTheme()
    {
        ThemeState.SetTheme(selectedMode, selectedColor);
    }

    private void HandleThemeChanged()
    {
        selectedMode = ThemeState.Mode;
        selectedColor = ThemeState.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeState.OnChange -= HandleThemeChanged;
    }
}

